text:
Here's a water tracker with a goal of 8 glasses. Tap a glass to fill it, or use + and − to adjust. It saves your count for today and starts fresh tomorrow.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:system-ui,sans-serif;margin:0;padding:20px;text-align:center;background:#f2f8fc;color:#12324a}
  h1{font-size:20px;margin:0 0 4px}
  #date{font-size:13px;opacity:.7;margin-bottom:16px}
  #count{font-size:44px;font-weight:700;margin:8px 0}
  #msg{min-height:20px;font-size:14px;margin-bottom:12px}
  #bar{height:10px;background:#d6e6f2;border-radius:6px;overflow:hidden;max-width:320px;margin:0 auto 18px}
  #fill{height:100%;width:0;background:#2a8bd0;transition:width .3s}
  #glasses{display:grid;grid-template-columns:repeat(4,56px);gap:10px;justify-content:center;margin-bottom:18px}
  .g{width:56px;height:64px;border:2px solid #2a8bd0;border-radius:4px 4px 12px 12px;background:#fff;cursor:pointer;font-size:24px}
  .g.full{background:#2a8bd0;color:#fff}
  .ctl button{font-size:18px;padding:8px 16px;margin:0 4px;border:0;border-radius:8px;background:#2a8bd0;color:#fff;cursor:pointer}
  .ctl button.alt{background:#8aa4b8}
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="date"></div>
  <div id="count">0 / 8</div>
  <div id="msg"></div>
  <div id="bar"><div id="fill"></div></div>
  <div id="glasses"></div>
  <div class="ctl">
    <button onclick="change(-1)">−</button>
    <button onclick="change(1)">+</button>
    <button class="alt" onclick="resetDay()">Reset</button>
  </div>
<script>
  var GOAL = 8;
  var today = new Date();
  var key = "water-" + today.toISOString().slice(0,10);
  var n = 0;
  try { n = parseInt(localStorage.getItem(key) || "0", 10) || 0; } catch (e) {}
  document.getElementById("date").textContent = today.toDateString();

  function save(){ try { localStorage.setItem(key, String(n)); } catch (e) {} }
  function change(d){ n = Math.max(0, Math.min(20, n + d)); save(); render(); }
  function resetDay(){ n = 0; save(); render(); }
  function setTo(i){ n = (n === i + 1) ? i : i + 1; save(); render(); }

  function render(){
    document.getElementById("count").textContent = n + " / " + GOAL;
    document.getElementById("fill").style.width = Math.min(100, n / GOAL * 100) + "%";
    document.getElementById("msg").textContent =
      n >= GOAL ? "Goal reached. Nicely done!" : (GOAL - n) + " more to go";
    var box = document.getElementById("glasses");
    box.innerHTML = "";
    for (var i = 0; i < GOAL; i++) {
      var b = document.createElement("button");
      b.className = "g" + (i < n ? " full" : "");
      b.textContent = i < n ? "💧" : "";
      b.setAttribute("aria-label", "Glass " + (i + 1));
      (function(j){ b.onclick = function(){ setTo(j); }; })(i);
      box.appendChild(b);
    }
  }
  render();
</script>
</body>
</html>
```
